        public static ParseResult FillBinaryRecordTypes(
            ILoadScreenInternal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                            item: item,
                            frame: frame,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            nextRecordType: nextRecordType,
                            contentLength: contentLength,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                        item.EDID = StringBinaryTranslation.Instance.Parse(
                            reader: frame.SpawnWithLength(contentLength),
                            stringBinaryType: StringBinaryType.NullTerminate,
                            parseWhole: true);
                        return new ParseResult((int)LoadScreen_FieldIndex.EDID, nextRecordType);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(nextRecordType) ?? 0)
                        {
                            case 0:
                                return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                                    item: item,
                                    frame: frame,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    nextRecordType: nextRecordType,
                                    contentLength: contentLength,
                                    translationParams: translationParams.WithNoConverter());
                            case 1:
                                frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                                item.EDID = StringBinaryTranslation.Instance.Parse(
                                    reader: frame.SpawnWithLength(contentLength),
                                    stringBinaryType: StringBinaryType.NullTerminate,
                                    parseWhole: true);
                                return new ParseResult((int)LoadScreen_FieldIndex.EDID, nextRecordType);
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.DESC:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.DESC = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.Normal,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)LoadScreen_FieldIndex.DESC;
                }
                case RecordTypeInts.BNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.BNAM = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)LoadScreen_FieldIndex.BNAM;
                }
                case RecordTypeInts.NNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.LoadingScreenNIF.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)LoadScreen_FieldIndex.LoadingScreenNIF;
                }
                case RecordTypeInts.TNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.Transform.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)LoadScreen_FieldIndex.Transform;
                }
                case RecordTypeInts.MOD2:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.MOD2 = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)LoadScreen_FieldIndex.MOD2;
                }
                case RecordTypeInts.PNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.PNAM = frame.ReadUInt8();
                    return (int)LoadScreen_FieldIndex.PNAM;
                }
                case RecordTypeInts.LSST:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.LSST = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
