        private int? _DropSoundLocation;
        public IFormLinkNullableGetter<IFallout76MajorRecordGetter> DropSound => FormLinkBinaryTranslation.Instance.NullableRecordOverlayFactory<IFallout76MajorRecordGetter>(_package, _recordData, _DropSoundLocation);
        #endregion
        partial void CustomFactoryEnd(
            OverlayStream stream,
            int finalPos,
            int offset);

        partial void CustomCtor();
        protected LoadScreenBinaryOverlay(
            MemoryPair memoryPair,
            BinaryOverlayFactoryPackage package)
            : base(
                memoryPair: memoryPair,
                package: package)
        {
            this.CustomCtor();
        }

        public static ILoadScreenGetter LoadScreenFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new LoadScreenBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static ILoadScreenGetter LoadScreenFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return LoadScreenFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)LoadScreen_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)LoadScreen_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.DESC:
                {
                    _DESCLocation = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.DESC;
                }
                case RecordTypeInts.BNAM:
                {
                    _BNAMLocation = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.BNAM;
                }
                case RecordTypeInts.NNAM:
                {
                    _LoadingScreenNIFLocation = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.LoadingScreenNIF;
                }
                case RecordTypeInts.TNAM:
                {
                    _TransformLocation = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.Transform;
                }
                case RecordTypeInts.MOD2:
                {
                    _MOD2Location = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.MOD2;
                }
                case RecordTypeInts.PNAM:
                {
                    _PNAMLocation = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.PNAM;
                }
                case RecordTypeInts.LSST:
                {
                    _LSSTLocation = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.LSST;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    this.Conditions = BinaryOverlayList.FactoryByCountPerItem<IConditionGetter>(
                        stream: stream,
                        package: _package,
                        countLength: 4,
                        trigger: Condition_Registration.TriggerSpecs,
                        countType: RecordTypes.CITC,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ConditionBinaryOverlay.ConditionFactory(new OverlayStream(s, p), p, recConv),
                        skipHeader: false);
                    return (int)LoadScreen_FieldIndex.Conditions;
                }
                case RecordTypeInts.ONAM:
                {
                    _ONAMLocation = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.ONAM;
                }
                case RecordTypeInts.ZNAM:
                {
                    _DropSoundLocation = (stream.Position - offset);
                    return (int)LoadScreen_FieldIndex.DropSound;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
